import SwiftUI
import UIKit

/// Emergency switch for the experimental still-screenshot compositor.
/// Keep this scoped to ChatView; RootView/auth must never depend on it.
enum GRUPrivacyFeatures {
    static let chatScreenshotShieldEnabled = true
}

private enum GRUPrivacyCaptureArtworkAsset {
    // Approved GRU privacy mock, compressed and embedded so the fallback is
    // available synchronously before a screenshot can be requested.
    private static let chunks: [String] = [
        "
            ",
        "            ",
        ""
    ]

    static let image: UIImage = {
        let encoded = chunks.joined()
        guard let data = Data(base64Encoded: encoded),
              let image = UIImage(data: data) else {
            return UIImage()
        }
        return image
    }()
}

struct GRUPrivacyCaptureArtwork: View {
    var onDismiss: (() -> Void)? = nil

    var body: some View {
        GeometryReader { proxy in
            ZStack {
                Color.black

                Image(uiImage: GRUPrivacyCaptureArtworkAsset.image)
                    .resizable()
                    .scaledToFill()
                    .frame(width: proxy.size.width, height: proxy.size.height)
                    .clipped()
            }
            .frame(width: proxy.size.width, height: proxy.size.height)
            .contentShape(Rectangle())
            .onTapGesture {
                onDismiss?()
            }
        }
        .ignoresSafeArea()
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("gru. privacy")
    }
}
